export const WHO_CAN_ADVISE = { en: "Two kinds of people can give immigration legal advice: lawyers, licensed and in good standing in any U.S. state, and DOJ-accredited representatives who work for a DOJ-recognized nonprofit. Some accredited representatives are 'DHS only': they can help with USCIS applications but cannot represent you in immigration court.", es: "Hay dos categorías de personas que pueden brindar asesoramiento legal en un caso de inmigración: abogados (con licencia vigente en cualquier estado) y representantes acreditados del Departamento de Justicia (DOJ), que trabajan para una organización sin fines de lucro reconocida por el DOJ. Algunos representantes acreditados son 'solo DHS': pueden ayudar con solicitudes ante USCIS, pero no pueden representarlo en la corte de inmigración." } satisfies Bilingual;
export const CARD_TEXT = { en: "What the card tells you (your side): Do not open the door if an immigration agent is knocking. Do not answer questions from an immigration agent; you have the right to remain silent. Do not sign anything before you talk to a lawyer; you have the right to speak with a lawyer. If you are outside your home, ask the agent if you are free to leave, and if they say yes, leave calmly. Give the card to the agent. If you are inside, show it through the window or slide it under the door.", es: "Usted tiene derechos constitucionales: NO ABRA LA PUERTA si un agente de inmigración está tocando la puerta. NO CONTESTE NINGUNA PREGUNTA de un agente de inmigración si trata de hablar con usted. Usted tiene el derecho a guardar silencio. NO FIRME NADA sin antes hablar con un abogado. Usted tiene el derecho de hablar con un abogado. Si usted está fuera de su casa, pregúntele al agente si tiene la libertad de irse y si le dice que sí, váyase con tranquilidad. ENTRÉGUELE ESTA TARJETA AL AGENTE. Si usted está dentro de su casa, muestre la tarjeta por la ventana o pásela debajo de la puerta." } satisfies Bilingual;
